for k in range(1,8):
    I_=np.array(G[f'Demo pair {k} input']); O_=np.array(G[f'Demo pair {k} output'])
    vals,cnts=np.unique(I_,return_counts=True); bg=int(vals[np.argmax(cnts)]); rare=int(next(v for v in vals if v!=bg))
    marks=[tuple(p) for p in np.argwhere(I_==rare)]
